from dataclasses import dataclass
@dataclass(frozen=True, slots=True)
class P:
    x: int
    y: int
@dataclass(frozen=True, slots=True, repr=False)
class Dot:
    _0: object
    def __repr__(self):
        return f"Dot({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class Line:
    _0: object
    _1: object
    def __repr__(self):
        return f"Line({self._0!r}, {self._1!r})"
@dataclass(frozen=True, slots=True, repr=False)
class Empty:
    def __repr__(self):
        return "Empty"
_Empty = Empty()
def walk(n, acc):
    while True:
        x = n * 2
        first = 1
        d = 3
        def score(sh):
            match sh:
                case Dot(P(x=x, y=y)) as d if x > 1:
                    return x + y
                case Line(P(x=first, y=_), q):
                    return first
                case Empty():
                    return 0
                case _:
                    return 1
        def head(xs):
            match xs:
                case [first, *rest]:
                    return first
                case []:
                    return 0
                case _:
                    raise RuntimeError("non-exhaustive match")
        def pick(p):
            match p:
                case (1, x) | (x, 1):
                    return x
                case _:
                    return 0
        if n == 0:
            return acc + x + first + d
        else:
            n, acc = (n - 1, acc + score(Dot(P(n, 1))) + head([n]) + pick((n, 1)))
            continue
